function largestInteger(num) {
  const digits = String(num).split('').map(Number);
  const odds = digits.filter(d => d % 2 === 1).sort((a, b) => b - a);
  const evens = digits.filter(d => d % 2 === 0).sort((a, b) => b - a);
  let oddIndex = 0;
  let evenIndex = 0;
  let result = 0;

  for (const digit of digits) {
    if (digit % 2 === 1) {
      result = result * 10 + odds[oddIndex];
      oddIndex++;
    } else {
      result = result * 10 + evens[evenIndex];
      evenIndex++;
    }
  }
  return result;
}

