function largestInteger(num) {
  // Explore every arrangement reachable by allowed swaps and keep the largest.
  const start = String(num);
  const seen = new Set([start]);
  const queue = [start];
  let best = num;
  for (let head = 0; head < queue.length; head++) {
    const cur = queue[head];
    best = Math.max(best, parseInt(cur, 10));
    for (let i = 0; i < cur.length; i++)
      for (let j = i + 1; j < cur.length; j++) {
        if ((cur.charCodeAt(i) - cur.charCodeAt(j)) % 2 !== 0 || cur[i] === cur[j]) continue;
        const arr = cur.split('');
        const tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
        const next = arr.join('');
        if (!seen.has(next)) { seen.add(next); queue.push(next); }
      }
  }
  return best;
}

