function generate(rand, size) {
  if (size === 'large') {
    if (rand() < 0.1) return [1000000000];
    let num = 1 + Math.floor(rand() * 9);
    for (let i = 0; i < 8; i++) num = num * 10 + Math.floor(rand() * 10);
    return [num];
  }
  const length = 1 + Math.floor(rand() * 6);
  const pool = rand() < 0.5 ? 10 : 4;
  let num = 1 + Math.floor(rand() * 9);
  for (let i = 1; i < length; i++) num = num * 10 + Math.floor(rand() * pool);
  return [num];
}
